mapper.select:
SELECT cipher_name AS cipherName,
       is_accepted AS accepted,
       key_size AS keySize,
       forward_secrecy AS forwardSecrecy,
       openssl_name AS opensslName
FROM cipher_suite_support
         LEFT JOIN scan_target ON cipher_suite_support.target_id = scan_target.target_id
         LEFT JOIN scan_task ON scan_task.task_id = scan_target.task_id
WHERE scan_task.task_id = #{taskId}

    AND scan_target.target_id = #{targetId}


    AND cipher_suite_support.tls_version = #{tlsVersion}

LIMIT #{offset}, #{size};

SELECT COUNT(*) AS total_count FROM ( SELECT cipher_name AS cipherName, is_accepted AS accepted, key_size AS keySize, forward_secrecy AS forwardSecrecy, openssl_name AS opensslName FROM cipher_suite_support LEFT JOIN scan_target ON cipher_suite_support.target_id = scan_target.target_id LEFT JOIN scan_task ON scan_task.task_id = scan_target.task_id WHERE scan_task.task_id = #{taskId}
AND scan_target.target_id = #{targetId}
AND cipher_suite_support.tls_version = #{tlsVersion}
) AS subquery
